"""Spotify delivery - via podcast RSS, because that is the only route
Spotify offers. See docs/SPOTIFY.md for the verified details.

There is NO public Spotify API endpoint that uploads an MP3 episode to
an account:
  * The Spotify Web API only adds items that already exist in the
    Spotify catalog to playlists/libraries; it cannot ingest new audio.
  * Spotify is a directory that reads an RSS feed generated by a podcast
    host; episodes are published on the host, not uploaded to Spotify.

So this module does the automatable, correct thing:
  1. Copy the homily MP3 into PODCAST_AUDIO_DIR (a folder served over
     public HTTPS - e.g. on the parish web host / a podcast host).
  2. Regenerate the podcast RSS feed (PODCAST_FEED_FILE) with the new
     episode: title, description, Sunday pubDate, GUID, and an
     <enclosure> pointing at PODCAST_AUDIO_BASE_URL/<file>.mp3.
  3. The feed is submitted ONCE to Spotify for Podcasters. After that,
     Spotify polls the feed and new episodes appear automatically.

If PODCAST_AUDIO_BASE_URL is not configured, this step is skipped with
a clear warning instead of pretending an upload happened.
"""
from __future__ import annotations

import os
import shutil
from datetime import datetime
from email.utils import format_datetime
from pathlib import Path
from xml.etree import ElementTree as ET
from zoneinfo import ZoneInfo

from config import Settings
from publish import atomic_copy

ITUNES = "http://www.itunes.com/dtds/podcast-1.0.dtd"
ET.register_namespace("itunes", ITUNES)


def _q(tag: str) -> str:
    return f"{{{ITUNES}}}{tag}"


def _load_feed(settings: Settings) -> ET.ElementTree:
    feed_file = settings.podcast_feed_file
    assert feed_file is not None
    if feed_file.exists():
        return ET.parse(feed_file)
    rss = ET.Element("rss", {"version": "2.0"})
    channel = ET.SubElement(rss, "channel")
    ET.SubElement(channel, "title").text = settings.podcast_title
    ET.SubElement(channel, "link").text = settings.podcast_feed_base_url or "https://www.oloj.org/"
    ET.SubElement(channel, "description").text = settings.podcast_description
    ET.SubElement(channel, "language").text = settings.podcast_language
    ET.SubElement(channel, _q("author")).text = settings.podcast_author
    ET.SubElement(channel, _q("explicit")).text = "false"
    category = ET.SubElement(channel, _q("category"), {"text": settings.podcast_category})
    ET.SubElement(category, _q("category"), {"text": settings.podcast_subcategory})
    if settings.podcast_artwork_url:
        ET.SubElement(channel, _q("image"), {"href": settings.podcast_artwork_url})
    if settings.podcast_contact_email:
        owner = ET.SubElement(channel, _q("owner"))
        ET.SubElement(owner, _q("email")).text = settings.podcast_contact_email
    return ET.ElementTree(rss)


def add_episode(settings: Settings, homily_mp3: Path, title: str,
                description: str, service_dt: datetime, guid_key: str) -> str | None:
    """Add (or replace) one episode in the feed. Returns the episode URL."""
    if not settings.podcast_audio_base_url:
        print("[spotify] SKIPPED: PODCAST_AUDIO_BASE_URL is not set. "
              "An RSS enclosure needs a public HTTPS URL for the MP3 - "
              "a local file alone cannot reach Spotify.")
        return None
    assert settings.podcast_audio_dir is not None and settings.podcast_feed_file is not None

    settings.podcast_audio_dir.mkdir(parents=True, exist_ok=True)
    dest_audio = atomic_copy(homily_mp3, settings.podcast_audio_dir / homily_mp3.name)
    audio_url = f"{settings.podcast_audio_base_url}/{dest_audio.name}"

    tree = _load_feed(settings)
    channel = tree.getroot().find("channel")
    assert channel is not None

    # Idempotent: drop any existing item with the same GUID first.
    for item in channel.findall("item"):
        guid_el = item.find("guid")
        if guid_el is not None and guid_el.text == guid_key:
            channel.remove(item)

    item = ET.Element("item")
    ET.SubElement(item, "title").text = title
    ET.SubElement(item, "description").text = description
    tz = ZoneInfo(settings.timezone)
    pub_dt = service_dt.replace(tzinfo=tz)
    ET.SubElement(item, "pubDate").text = format_datetime(pub_dt)
    ET.SubElement(item, "guid", {"isPermaLink": "false"}).text = guid_key
    ET.SubElement(item, "enclosure", {
        "url": audio_url,
        "length": str(dest_audio.stat().st_size),
        "type": "audio/mpeg",
    })
    ET.SubElement(item, _q("author")).text = settings.podcast_author
    ET.SubElement(item, _q("explicit")).text = "false"

    # Newest episode first, after the channel metadata elements.
    insert_at = 0
    for i, child in enumerate(list(channel)):
        if child.tag == "item":
            insert_at = i
            break
        insert_at = i + 1
    channel.insert(insert_at, item)

    settings.podcast_feed_file.parent.mkdir(parents=True, exist_ok=True)
    tmp = settings.podcast_feed_file.with_suffix(".xml.tmp")
    tree.write(tmp, encoding="utf-8", xml_declaration=True)
    os.replace(tmp, settings.podcast_feed_file)
    print(f"[spotify] Episode added to RSS feed: {title} -> {audio_url}")
    print(f"[spotify] Feed updated: {settings.podcast_feed_file} "
          "(Spotify ingests new episodes from the feed automatically.)")
    return audio_url
